import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware for request logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Authentication middleware - checks session token
async function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No session token' });

  const result = await pool.query(
    'SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()',
    [token]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid session' });
  req.user = result.rows[0];
  next();
}

// Search endpoint with filtering
app.get('/api/v2/documents/search', authenticate, async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;

    let baseQuery = `SELECT d.id, d.title, d.category, d.created_at, d.owner_id
                     FROM documents d WHERE d.org_id = $1`;
    const params = [req.user.org_id];
    let paramIdx = 2;

    if (q) {
      baseQuery += ` AND (d.title ILIKE $${paramIdx} OR d.content ILIKE $${paramIdx})`;
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (category) {
      baseQuery += ` AND d.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'category', 'updated_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY d.${sortCol} ${sortOrder}`;

    // Limit handling
    const parsedLimit = parseInt(limit) || 50;
    baseQuery += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin analytics endpoint
app.get('/api/v2/admin/analytics', authenticate, async (req, res) => {
  const { metric, group_by, date_from, date_to } = req.query;

  // Role check
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }

  try {
    // Build analytics query with user-controlled grouping
    const query = `SELECT ${group_by}, COUNT(*) as count, 
                   SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) as active_count
                   FROM documents 
                   WHERE created_at BETWEEN $1 AND $2
                   GROUP BY ${group_by}
                   ORDER BY count DESC`;

    const result = await pool.query(query, [date_from, date_to]);
    res.json({ analytics: result.rows });
  } catch (err) {
    console.error('Analytics error:', err.message);
    res.status(500).json({ error: 'Analytics query failed' });
  }
});

// Document export endpoint
app.post('/api/v2/documents/export', authenticate, async (req, res) => {
  const { doc_ids, format } = req.body;

  if (!Array.isArray(doc_ids) || doc_ids.length === 0) {
    return res.status(400).json({ error: 'doc_ids required' });
  }

  const placeholders = doc_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM documents WHERE org_id = $1 AND id IN (${placeholders})`;
  const result = await pool.query(query, [req.user.org_id, ...doc_ids]);

  res.json({ exported: result.rows, format: format || 'json' });
});

app.listen(3000, () => console.log('Document service running on :3000'));
